$(document).on('click','[data-dashboard-punch]',e=>{
  e.preventDefault();
  if(window.innerWidth<=700 && $(e.currentTarget).closest('.bb-global-quick-actions').length){this.navigateView('attendspace');return;}
  this.dashboardPunchAttendance();
});
$(document).on('click','[data-dashboard-add-note]',e=>{
  e.preventDefault();
  if(window.innerWidth<=700 && $(e.currentTarget).closest('.bb-global-quick-actions').length){this.searchQuery='';this.activeNotespace=null;this.navigateView('notespaces');return;}
  this.dashboardQuickNote();
});
$(document).on('click','[data-dashboard-add-task]',e=>{
  e.preventDefault();
  const workspaces=(this.state.workspaces||[]).filter(w=>this.areasForWorkspace(w.id).some(a=>this.canAddTaskInArea(w.id,a)));
  if(!workspaces.length){this.toast('No Workspace / Work Area available for adding a task');return;}
  let ws=workspaces.find(w=>String(w.id)===String(this.activeWorkspace||''))||workspaces[0];
  let areas=this.areasForWorkspace(ws.id).filter(a=>this.canAddTaskInArea(ws.id,a));
  if(!areas.length){
    ws=workspaces.find(w=>this.areasForWorkspace(w.id).some(a=>this.canAddTaskInArea(w.id,a)))||workspaces[0];
    areas=this.areasForWorkspace(ws.id).filter(a=>this.canAddTaskInArea(ws.id,a));
  }
  const area=areas[0];
  if(!area){this.toast('No Work Area available for adding a task');return;}
  this.openQuickTask(String(ws.id),String(area.id),'dashboard');
});

