  const input=$(e.currentTarget),picker=input.closest('.bb-edit-task-area-picker'),q=String(input.val()||'').trim().toLowerCase();let shown=0;
  picker.find('.bb-edit-task-area-option').each((_,el)=>{const match=!q||String($(el).text()||'').toLowerCase().includes(q);$(el).toggle(match);if(match)shown++;});
