$(document).on('click','.bb-dashboard-task-area-option',e=>{
  e.preventDefault();e.stopPropagation();
  const b=$(e.currentTarget),f=b.closest('.bb-quick-task-card'),wid=String(b.attr('data-workspace-id')||''),aid=String(b.attr('data-work-area-id')||''),label=String(b.attr('data-task-area-label')||b.text()||'').trim();
  // Preserve CallSpace context and entered values when changing Work Area. openQuickTask()
  // rebuilds the dashboard task form, so without this the hidden CallSpace source id was lost
  // and the created task could not be counted against the CallSpace row.
  const sourceCallSpaceId=String(f.find('[name=source_callspace_id]').val()||'');
  const preservedTaskName=String(f.find('[name=task_name]').val()||'');
  const preservedDescription=String(f.find('[name=description]').val()||'');
  f.find('[name=dashboard_workspace_id]').val(wid);
  f.find('[name=dashboard_work_area_id]').val(aid);
  f.find('.bb-dashboard-task-area-summary').text(label);
  f.find('.bb-dashboard-task-area-picker').removeAttr('open');
  f.find('.bb-dashboard-task-area-search').val('');
  f.find('.bb-dashboard-task-area-option').prop('hidden',false);
  f.find('.bb-dashboard-task-area-empty').prop('hidden',true);
  if(wid&&aid){
    this.openQuickTask(wid,aid,'dashboard');
    if(sourceCallSpaceId){
      const nf=$('#bb-modal .bb-quick-task-card').first();
      if(nf.length){
        nf.find('[name=source_callspace_id]').remove();
        nf.append(`<input type="hidden" name="source_callspace_id" value="${this.attr(sourceCallSpaceId)}">`);
        nf.find('[name=task_name]').val(preservedTaskName).trigger('input').trigger('change');
        nf.find('[name=description]').val(preservedDescription).trigger('input').trigger('change');
        this.refreshTaskNameValidation(nf);this.syncQuickActionStates(nf);
      }
    }
  }
});
