$(document).on('click','[data-holiday-delete-row]',e=>{
  e.preventDefault();e.stopPropagation();if(!this.isPrivilegedIdentity())return;
  const row=$(e.currentTarget).closest('.bb-holiday-master-row'),
        id=String(row.find('[data-holiday-id]').val()||row.attr('data-holiday-id')||''),
        date=String(row.find('[data-holiday-date]').val()||''),
        name=String(row.find('[data-holiday-name]').val()||'Holiday');

  if(!id){
    row.remove();
    if(!$('.bb-holiday-master tbody tr').length)$('.bb-holiday-master tbody').append(this.holidayMasterRow({}));
    return;
  }

  if(!confirm(`Delete ${name||'Holiday'}${date?' ('+this.formatDate(date)+')':''}?`))return;

  const btn=$(e.currentTarget).prop('disabled',true);
  this.api('bb_delete_attendance_holiday',{id}).done(r=>{
    if(!r.success){btn.prop('disabled',false);this.toast(r.data?.message||'Could not delete Holiday');return;}
    this.state.attendanceHolidays=(this.state.attendanceHolidays||[]).filter(x=>String(x.id)!==id);
    row.remove();
    if(!$('.bb-holiday-master tbody tr').length)$('.bb-holiday-master tbody').append(this.holidayMasterRow({}));
    $('.bb-holiday-master .bb-record-count').text(`${this.state.attendanceHolidays.length} holiday${this.state.attendanceHolidays.length===1?'':'s'}`);
    this.toast('Holiday deleted');
  }).fail(()=>{btn.prop('disabled',false);this.toast('Could not delete Holiday');});
});

