// v4.5.0: Dual Quick Add — Daily recurring or One-Time. Batch entry keeps the selected quick-add mode and session options.
// v4.3.1: close mobile filter panel and open multi-select menus when tapping outside them.
$(document).on('click',e=>{
  if(this.view!=='workspace') return;
  const $target=$(e.target);
  // Keep the panel open while interacting with the top funnel, the filter panel or a filter dropdown.
  if($target.closest('.bb-mobile-filter-top,.bb-compact-filters,.bb-multi-filter').length) return;
  $('.bb-workspace-toolbar').removeClass('filters-open');$('.bb-mobile-filter-top').removeClass('active').attr('aria-expanded','false');
  $('details.bb-multi-filter[open]').removeAttr('open');
});
// Clicking elsewhere inside the filter panel closes any other open multi-select dropdown.
$(document).on('click','.bb-compact-filters',e=>{
  const current=$(e.target).closest('details.bb-multi-filter')[0];
  $('details.bb-multi-filter[open]').each((_,el)=>{if(el!==current) el.removeAttribute('open');});
});
// v4.13.10: keep Workspace filter dropdowns visible even when the one-line toolbar scrolls horizontally.
const positionWorkspaceFilterMenu=(detailsEl)=>{
  if(!detailsEl||!detailsEl.open)return;
  const summary=detailsEl.querySelector(':scope > summary');
  const menu=detailsEl.querySelector(':scope > .bb-multi-menu');
  if(!summary||!menu)return;
  const r=summary.getBoundingClientRect();
  const gap=5;
  const preferred=Math.max(210,Math.min(300,Math.max(r.width,230)));
  let left=r.left;
  if(left+preferred>window.innerWidth-10)left=Math.max(10,window.innerWidth-preferred-10);
  const below=r.bottom+gap;
  const maxH=Math.min(300,Math.max(140,window.innerHeight-below-12));
  detailsEl.style.setProperty('--bb-filter-menu-left',`${Math.round(left)}px`);
  detailsEl.style.setProperty('--bb-filter-menu-top',`${Math.round(below)}px`);
  detailsEl.style.setProperty('--bb-filter-menu-width',`${Math.round(preferred)}px`);
  detailsEl.style.setProperty('--bb-filter-menu-maxh',`${Math.round(maxH)}px`);
};

