App.attendanceScheduledOut=function(emp){
  return Number(emp?.use_org_work_hours||0)!==0
    ?String(this.state.attendanceSettings?.defaultOutTime||this.state.orgSettings?.attendanceDefaultOutTime||'18:00')
    :String(emp?.out_time||'18:00');
};
App.attendanceScheduledMinutes=function(emp){
  const start=this.attendanceTimeMinutes(this.attendanceScheduledIn(emp));
  const end=this.attendanceTimeMinutes(this.attendanceScheduledOut(emp));
  if(start===null||end===null)return 1;
  const span=end>=start?end-start:(1440-start)+end;
  const settings=this.state.attendanceSettings||{};
  const standardBreak=Math.max(0,Number(settings.standardBreakMinutes??45));
  // v4.16.57: Never deduct the default break when Working Hour is under 8 hours.
  // For 8-hour-or-longer attendance, continue respecting the configured Auto Break Applies After threshold.
  const autoAfter=Math.max(480,Number(settings.autoBreakAfterMinutes??360));
  const scheduledBreak=span>=autoAfter?standardBreak:0;
  return Math.max(1,span-scheduledBreak);
};
