// Shared post-save refresh: retain the user's position, expanded sections and filters.
refreshAfterFormSave(){
  // Save confirmation already came from the server. Synchronize data asynchronously;
  // never navigate, reload the document or reset current Workspace filters.
  const view=this.view,workspace=String(this.activeWorkspace||'');
  const windowY=window.scrollY||0;
  const selectors=['.bb-board-scroll-dock','.bb-workspace-board-scroll','.bb-table-wrap','.bb-main','.bb-content','.bb-sidebar'];
  const scrollers=selectors.map(selector=>{const el=document.querySelector(selector);return el?{selector,top:el.scrollTop,left:el.scrollLeft}:null;}).filter(Boolean);
  const query=String(this.workspaceSearchQuery||''),localQuery=String(this.searchQuery||'');
  const openCompleted=[...document.querySelectorAll('.bb-bucket-completed:not(.is-collapsed)')].map(el=>String(el.closest('[data-area-id]')?.getAttribute('data-area-id')||'')).filter(Boolean);
  const previousGroup=this.workspaceGroupBy,previousMode=this.workspaceViewMode;
  const restore=()=>{
    if(this.view!==view||(workspace&&String(this.activeWorkspace||'')!==workspace))return;
    this.workspaceSearchQuery=query;this.searchQuery=localQuery;
    this.workspaceGroupBy=previousGroup;this.workspaceViewMode=previousMode;
    requestAnimationFrame(()=>{
      openCompleted.forEach(id=>{const area=document.querySelector('.bb-workarea-column[data-area-id="'+CSS.escape(id)+'"]');if(area)area.querySelectorAll('.bb-bucket-completed').forEach(el=>el.classList.remove('is-collapsed'));});
      for(const saved of scrollers){const el=document.querySelector(saved.selector);if(el){el.scrollTop=saved.top;el.scrollLeft=saved.left;}}
      window.scrollTo(0,windowY);
      if(this.view==='workspace')this.applyBoardFilters();
    });
  };
  // Quiet background state sync; no browser refresh, URL navigation or loading overlay.
  this.refreshStateQuietly(restore);
},
