setupBoardScrollProxy(){
const main=document.querySelector('.bb-board-scroll'),dock=document.querySelector('.bb-board-scroll-dock'),range=document.querySelector('.bb-board-scroll-range');
if(!main||!dock||!range)return;
if(this._boardProxyResizeHandler)window.removeEventListener('resize',this._boardProxyResizeHandler);
if(this._boardProxyScrollHandler)window.removeEventListener('scroll',this._boardProxyScrollHandler);
if(this._boardProxyObserver){try{this._boardProxyObserver.disconnect();}catch(e){}}
if(this._boardMainScrollHandler)main.removeEventListener('scroll',this._boardMainScrollHandler);
if(this._boardRangeInputHandler)range.removeEventListener('input',this._boardRangeInputHandler);
if(this._boardWheelHandler)main.removeEventListener('wheel',this._boardWheelHandler);
let syncing=false;
const leftBtn=dock.querySelector('.bb-board-slide-left'),rightBtn=dock.querySelector('.bb-board-slide-right');
const maxScroll=()=>Math.max(0,main.scrollWidth-main.clientWidth);
const workspaceScrollKey=this.view==='workspace'&&this.activeWorkspace?`bb_workspace_scroll_${String(this.activeWorkspace)}`:'';
const saveWorkspaceScroll=()=>{
  if(!workspaceScrollKey)return;
  try{
    sessionStorage.setItem(workspaceScrollKey,JSON.stringify({
      left:Math.max(0,main.scrollLeft||0),
      max:maxScroll(),
      at:Date.now()
    }));
  }catch(_e){}
};
const restoreWorkspaceScroll=()=>{
  if(!workspaceScrollKey)return;
  try{
    const raw=sessionStorage.getItem(workspaceScrollKey);
    if(!raw)return;
    const saved=JSON.parse(raw)||{};
    const max=maxScroll();
    let left=Math.max(0,Number(saved.left||0));
    if(Number(saved.max||0)>0&&max>0&&left>max){
      left=max*(left/Number(saved.max));
    }
    main.scrollLeft=Math.min(max,left);
  }catch(_e){}
};
const syncRange=()=>{const max=maxScroll();const pct=max?Math.max(0,Math.min(100,(main.scrollLeft/max)*100)):0;range.value=String(pct);range.disabled=max<2;if(leftBtn)leftBtn.disabled=main.scrollLeft<=2;if(rightBtn)rightBtn.disabled=main.scrollLeft>=max-2;};
const position=()=>{
  const r=main.getBoundingClientRect(),portrait=window.matchMedia&&window.matchMedia('(orientation: portrait)').matches&&window.innerWidth<=1366;
  const usableLeft=Math.max(0,r.left),usableRight=Math.max(0,window.innerWidth-Math.min(window.innerWidth,r.right));
  dock.style.left=(usableLeft+4)+'px';dock.style.right=(usableRight+4)+'px';dock.style.width='auto';
  const desktop=window.innerWidth>900&&!portrait;
  dock.style.display=desktop?'flex':'none';
  if(desktop)requestAnimationFrame(syncRange);
};
this._boardMainScrollHandler=()=>{if(!syncing){syncing=true;syncRange();syncing=false;}saveWorkspaceScroll();};
this._boardRangeInputHandler=()=>{if(syncing)return;syncing=true;const max=maxScroll();main.scrollLeft=max*(Number(range.value||0)/100);syncing=false;syncRange();saveWorkspaceScroll();};
main.addEventListener('scroll',this._boardMainScrollHandler,{passive:true});
range.addEventListener('input',this._boardRangeInputHandler,{passive:true});
this._boardWheelHandler=(e)=>{if((e.shiftKey&&Math.abs(e.deltaY)>0)||Math.abs(e.deltaX)>Math.abs(e.deltaY)){const delta=e.shiftKey?e.deltaY:e.deltaX;if(delta){e.preventDefault();main.scrollLeft+=delta;}}};
main.addEventListener('wheel',this._boardWheelHandler,{passive:false});
if(leftBtn)leftBtn.addEventListener('click',()=>main.scrollBy({left:-Math.max(280,main.clientWidth*.7),behavior:'smooth'}));
if(rightBtn)rightBtn.addEventListener('click',()=>main.scrollBy({left:Math.max(280,main.clientWidth*.7),behavior:'smooth'}));
this._boardProxyResizeHandler=position;this._boardProxyScrollHandler=position;
window.addEventListener('resize',position,{passive:true});
window.addEventListener('scroll',position,{passive:true});
if(window.ResizeObserver){this._boardProxyObserver=new ResizeObserver(()=>{position();syncRange();});this._boardProxyObserver.observe(main);const board=main.querySelector('.bb-board');if(board)this._boardProxyObserver.observe(board);}
requestAnimationFrame(()=>{position();requestAnimationFrame(()=>{restoreWorkspaceScroll();syncRange();});});
},
