beginInlineTitle(el,x=null,y=null){if(el.attr('contenteditable')==='true')return;const id=String(el.data('task-id')),t=this.taskById(id);if(!t)return;const old=String(t.task_name||el.text()||'');el.data('old',old).data('cancel',0).addClass('bb-inline-editing').attr('contenteditable','true').attr('spellcheck','true').attr('aria-label','Editing task name');const node=el[0];if(!node)return;node.focus({preventScroll:true});requestAnimationFrame(()=>{try{const sel=window.getSelection();let range=null;if(x!==null&&y!==null&&document.caretRangeFromPoint)range=document.caretRangeFromPoint(x,y);if(!range||!node.contains(range.startContainer)){range=document.createRange();range.selectNodeContents(node);range.collapse(false);}sel.removeAllRanges();sel.addRange(range);}catch(_e){}node.scrollIntoView?.({block:'nearest',behavior:'smooth'});});},
