   const body=`<input type="search" class="bb-inline-label-search" placeholder="Search labels"><div class="bb-inline-checks bb-inline-label-list">${list()||'<small class="bb-no-labels">No labels yet</small>'}</div><div class="bb-inline-keep-add"><button type="button" class="bb-keep-add-label">＋ <span>Add Label</span></button></div>`;
   const pop=this.placeInlinePopover(btn,this.inlinePopoverShell('Labels',body,'bb-label-pop'));
   const commit=()=>{const seen=new Set(),vals=[];pop.find('.bb-inline-label-list input:checked').each((_,x)=>{const v=cleanLabel(x.value),k=keyLabel(v);if(v&&!seen.has(k)){seen.add(k);vals.push(v);}});const value=vals.join(', ');this.inlineUpdate(id,'labels',value,()=>{t.labels=value;const d=vals.length?vals[0]+(vals.length>1?` +${vals.length-1}`:''):'';btn.html(d?this.esc(d):'<span class="bb-meta-icon">🏷️</span>').toggleClass('has-value',!!d).toggleClass('is-empty',!d);},false);};
   const finishNewLabel=(input,addAnother=false)=>{const $input=$(input);if($input.data('saving'))return;const val=cleanLabel($input.val());if(!val){$input.closest('.bb-keep-new-row').remove();if(addAnother)pop.find('.bb-keep-add-label').trigger('click');return;}$input.data('saving',1);const k=keyLabel(val);const exists=pop.find('.bb-inline-label-list input').filter((_,x)=>keyLabel(x.value)===k).first();if(exists.length){exists.prop('checked',true);$input.closest('.bb-keep-new-row').remove();commit();if(addAnother)pop.find('.bb-keep-add-label').trigger('click');return;}canonical.set(k,val);all.push(val);all.sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));selectedKeys.add(k);const row=$(`<label data-label-row="${this.attr(k)}"><input type="checkbox" checked><span></span></label>`);row.find('input').val(val);row.find('span').text(val);pop.find('.bb-no-labels').remove();const listBox=pop.find('.bb-inline-label-list');const rows=listBox.children('label').get();const before=rows.find(el=>String($(el).find('input').val()||'').localeCompare(val,undefined,{sensitivity:'base'})>0);before?row.insertBefore(before):listBox.append(row);$input.closest('.bb-keep-new-row').remove();commit();if(addAnother)pop.find('.bb-keep-add-label').trigger('click');};
   pop.on('input','.bb-inline-label-search',e=>{const q=keyLabel(e.currentTarget.value||'');pop.find('.bb-inline-label-list label').each((_,el)=>$(el).toggle(!q||keyLabel($(el).text()).includes(q)));});
   pop.on('change','.bb-inline-label-list input',commit);
   pop.on('click','.bb-keep-add-label',e=>{e.preventDefault();e.stopPropagation();const existing=pop.find('.bb-keep-new-label').first();if(existing.length){const text=cleanLabel(existing.val());if(text){finishNewLabel(existing[0],true);}else{existing.trigger('focus');}return;}const row=$(`<div class="bb-keep-new-row"><span class="bb-keep-plus">＋</span><input type="text" class="bb-keep-new-label" placeholder="Add Label" autocomplete="off"><button type="button" class="bb-keep-new-cancel" aria-label="Cancel">×</button></div>`);pop.find('.bb-inline-keep-add').before(row);requestAnimationFrame(()=>row.find('input').trigger('focus'));});
   pop.on('blur','.bb-keep-new-label',e=>setTimeout(()=>{if(document.activeElement&&$(document.activeElement).hasClass('bb-keep-new-cancel'))return;finishNewLabel(e.currentTarget,false);},80));
   pop.on('keydown','.bb-keep-new-label',e=>{if(e.key==='Enter'){e.preventDefault();finishNewLabel(e.currentTarget,true);}else if(e.key==='Escape'){e.preventDefault();$(e.currentTarget).closest('.bb-keep-new-row').remove();}});
   pop.on('click','.bb-keep-new-cancel',e=>{e.preventDefault();$(e.currentTarget).closest('.bb-keep-new-row').remove();});return;
