 const keepNewSubtaskVisible=$target=>{if(!$target||!$target.length)return;requestAnimationFrame(()=>{const rowEl=$target.closest('.bb-keep-new-subtask-row')[0]||$target[0],popEl=pop[0];if(!rowEl||!popEl)return;const rr=rowEl.getBoundingClientRect(),pr=popEl.getBoundingClientRect(),head=pop.find('.bb-inline-pop-head')[0],headH=head?head.getBoundingClientRect().height:0;const topLimit=pr.top+headH+8,bottomLimit=pr.bottom-12;if(rr.top<topLimit)popEl.scrollTop-=Math.ceil(topLimit-rr.top);else if(rr.bottom>bottomLimit)popEl.scrollTop+=Math.ceil(rr.bottom-bottomLimit);});};
