  if($ghost)$ghost.remove();if($activeArea)$activeArea.removeClass('bb-task-drop-target');
  $('.bb-cross-created').each((_,el)=>{if(!$(el).find('.bb-task').length)$(el).remove();});
  $item.removeClass('bb-dragging bb-drag-placeholder bb-area-drag-placeholder').css('pointer-events','');$('body').removeClass('bb-sort-active');
  if(!dragging)return;
  if(type!=='task'){this.persistWorkAreaOrder($container);return;}
  const $destArea=$item.closest('.bb-workarea-column'),destAreaId=String($destArea.data('area-id')||'');const $destList=$item.closest('.bb-task-list');
