  const $scoreWrap=$('.bb-workarea-score-card').first().parent();
  if($scoreWrap.length)ids.forEach(id=>{const $el=$scoreWrap.children(`.bb-workarea-score-card[data-score-area="${id}"]`);if($el.length)$scoreWrap.append($el);});
