setupWorkAreaResizers(){
  if(window.innerWidth<=900)return;
  $('.bb-workarea-column').each((_,el)=>{
    const col=$(el);
    if(col.children('.bb-workarea-resize-handle').length)return;
    const handle=$('<button type="button" class="bb-workarea-resize-handle" title="Drag to resize Work Area" aria-label="Resize Work Area"></button>');
    col.append(handle);
  });
  $(document).off('pointerdown.bbwaresize','.bb-workarea-resize-handle').on('pointerdown.bbwaresize','.bb-workarea-resize-handle',e=>{
    if(e.button!==undefined&&e.button!==0)return;
    e.preventDefault();e.stopPropagation();
    const handle=e.currentTarget,col=handle.closest('.bb-workarea-column');
    if(!col)return;
    const startX=e.clientX,startW=col.getBoundingClientRect().width;
    const minW=240,maxW=Math.max(minW,Math.min(window.innerWidth*0.72,760));
    handle.setPointerCapture?.(e.pointerId);
    col.classList.add('bb-resizing');document.body.classList.add('bb-workarea-resize-active');
    const move=ev=>{const w=Math.max(minW,Math.min(maxW,startW+(ev.clientX-startX)));col.style.setProperty('width',w+'px','important');col.style.setProperty('min-width',w+'px','important');col.style.setProperty('max-width',w+'px','important');};
    const end=ev=>{try{handle.releasePointerCapture?.(ev.pointerId)}catch(_e){}col.classList.remove('bb-resizing');document.body.classList.remove('bb-workarea-resize-active');handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);};
    handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);
  });
},
setupNoteAreaResizers(){
  if(window.innerWidth<=900)return;
  $('.bb-note-area-column').each((_,el)=>{
    const col=$(el),areaId=String(col.data('note-area-id')||''),nsId=String(this.activeNotespace||'');
    if(areaId){
      try{
        const saved=Number(localStorage.getItem(`bb_note_area_width_${nsId}_${areaId}`)||0);
        if(saved>=260){
          const w=Math.max(260,Math.min(saved,Math.max(260,Math.min(window.innerWidth*.78,900))));
          col[0].style.setProperty('width',w+'px','important');
          col[0].style.setProperty('min-width',w+'px','important');
          col[0].style.setProperty('max-width',w+'px','important');
        }
      }catch(_e){}
    }
    if(col.children('.bb-note-area-resize-handle').length)return;
    col.append('<button type="button" class="bb-note-area-resize-handle" title="Drag to resize Note Area" aria-label="Resize Note Area"><span></span></button>');
  });
  $(document).off('pointerdown.bbnarresize','.bb-note-area-resize-handle').on('pointerdown.bbnarresize','.bb-note-area-resize-handle',e=>{
    if(e.button!==undefined&&e.button!==0)return;
    e.preventDefault();e.stopPropagation();
    const handle=e.currentTarget,col=handle.closest('.bb-note-area-column');
    if(!col)return;
    const startX=e.clientX,startW=col.getBoundingClientRect().width,areaId=String($(col).data('note-area-id')||''),nsId=String(this.activeNotespace||'');
    const minW=260,maxW=Math.max(minW,Math.min(window.innerWidth*.78,900));
    handle.setPointerCapture?.(e.pointerId);
    col.classList.add('bb-note-area-resizing');document.body.classList.add('bb-note-area-resize-active');
    const move=ev=>{const w=Math.max(minW,Math.min(maxW,startW+(ev.clientX-startX)));col.style.setProperty('width',w+'px','important');col.style.setProperty('min-width',w+'px','important');col.style.setProperty('max-width',w+'px','important');};
    const end=ev=>{
      try{handle.releasePointerCapture?.(ev.pointerId)}catch(_e){}
      const finalW=Math.round(col.getBoundingClientRect().width);
      if(areaId){try{localStorage.setItem(`bb_note_area_width_${nsId}_${areaId}`,String(finalW));}catch(_e){}}
      col.classList.remove('bb-note-area-resizing');document.body.classList.remove('bb-note-area-resize-active');
      handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);handle.removeEventListener('pointercancel',end);
    };
    handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);
  });
},
persistWorkAreaOrder(board){const ids=$(board).children('.bb-workarea-column').map((_,el)=>Number($(el).data('area-id'))).get().filter(Boolean);if(!ids.length)return;const workspaceId=this.activeWorkspace;this.syncWorkAreaOrderUI(board,ids);this.api('bb_reorder_work_areas',{workspace_id:workspaceId,work_area_ids:ids}).done(r=>{if(r.success){const map=this.state.workspaceAreas.filter(x=>String(x.workspace_id)===String(workspaceId));ids.forEach((id,i)=>{const row=map.find(x=>Number(x.work_area_id)===Number(id));if(row)row.sort_order=i;});}else{this.toast(r.data?.message||'Could not save Work Area order');this.load();}}).fail(()=>{this.toast('Could not save Work Area order');this.load();});},
searchableMultiFilter(key,label,items=[]){const rows=items.map(([id,name])=>`<label><input class="bb-filter-check" type="checkbox" value="${this.attr(id)}"><span>${this.esc(name)}</span></label>`).join('');return `<details class="bb-multi-filter bb-searchable-filter" data-filter="${this.attr(key)}" data-label="${this.attr(label)}"><summary>${this.esc(label)}</summary><div class="bb-multi-menu"><div class="bb-filter-search-wrap"><span aria-hidden="true">⌕</span><input class="bb-filter-search-input" type="text" autocomplete="off" placeholder="Search ${this.esc(label)}..."></div>${rows||'<small class="bb-filter-empty-static">No options</small>'}<small class="bb-filter-no-results" hidden>No results found</small></div></details>`;},
