restoreBoardFilters(){const st=this.boardFilterState||{area:[],stage:[],priority:[],assignee:[],labels:[],completed:false};['area','stage','priority','assignee','labels'].forEach(key=>{const box=$(`.bb-multi-filter[data-filter="${key}"]`);if(!box.length)return;const vals=(st[key]||[]).map(String);box.find('.bb-filter-check').each((_,el)=>$(el).prop('checked',vals.includes(String(el.value))));this.updateMultiFilterLabel(box);});$('.bb-completed-filter-chip').toggleClass('active',!!st.completed);},
sortPinned(list,completed=false){return [...list].sort((a,b)=>{const ap=a.pinned_at?1:0,bp=b.pinned_at?1:0;if(ap!==bp)return bp-ap;if(ap&&bp){const c=String(a.pinned_at).localeCompare(String(b.pinned_at));if(c)return c;}if(completed)return String(b.completed_at||'').localeCompare(String(a.completed_at||''));const ad=String(a.due_date||a.occurrence_date||''),bd=String(b.due_date||b.occurrence_date||'');if(ad||bd){if(ad!==bd)return ad.localeCompare(bd);const at=String(a.due_time||''),bt=String(b.due_time||'');if(at!==bt)return at.localeCompare(bt);}const ao=Number(a.sort_order||0),bo=Number(b.sort_order||0);if(ao!==bo)return ao-bo;return Number(a.id||0)-Number(b.id||0);});},
togglePin(id,pin){this.api('bb_toggle_pin_task',{id,pin:pin?1:0}).done(r=>{if(r.success){this.toast(pin?'Flash highlight on — task kept on top':'Flash highlight removed');this.load()}else this.toast(r.data?.message||'Could not update Flash highlight')});},
score(ts,archives=[]){const due=ts.filter(t=>t.status==='Completed'||t.status==='Overdue');let early=due.filter(t=>t.status==='Completed'&&t.completion_result==='Early').length,on=due.filter(t=>t.status==='Completed'&&t.completion_result==='On Time').length,late=due.filter(t=>t.status==='Completed'&&t.completion_result==='Late').length,missed=due.filter(t=>t.status==='Overdue').length,total=due.length,points=(early+on)*100+late*60;archives.forEach(a=>{early+=Number(a.early_count||0);on+=Number(a.on_time_count||0);late+=Number(a.late_count||0);missed+=Number(a.missed_count||0);total+=Number(a.due_count||0);points+=Number(a.total_points||0)});const score=total?Math.round(points/total):0;return{score,early,on,late,missed,total};},
