renderDashboard(q=''){this.setHeader('Dashboard','');const query=String(q||'').trim().toLowerCase();const acts=this.state.activity||[];const updateActions=new Set(['task_in_progress','task_completed','remark_added','task_updated']);const workspaces=(this.state.workspaces||[]).filter(w=>!query||String(w.name||'').toLowerCase().includes(query));const visible=workspaces.map(w=>{const wa=acts.filter(a=>String(a.workspace_id)===String(w.id));const added=wa.filter(a=>String(a.action)==='task_created').length;const updated=wa.filter(a=>updateActions.has(String(a.action))).length;return {w,added,updated};}).filter(x=>x.added>0||x.updated>0);const cards=visible.map((x,i)=>`<button class="bb-summary-workspace bb-summary-tone-${(i%6)+1}" data-open-workspace="${x.w.id}"><strong>${this.esc(x.w.name)}</strong><div class="bb-summary-metrics"><span><small>Tasks Added</small><b>${x.added}</b></span><span><small>Tasks Updated</small><b>${x.updated}</b></span></div></button>`).join('');const quick=this.globalQuickActionsHtml();$('#bb-content').html(`<div class="bb-summary-shell"><div class="bb-summary-head"><h2>Daily Dashboard</h2>${quick}</div><div class="bb-summary-list">${cards||(query?'<div class="bb-empty-mini">No matching Workspace with activity</div>':'<div class="bb-empty-mini">No task activity to show</div>')}</div></div>`);},
