       const existing=Object.assign({},this.taskById(editId)||{}, {id:editId,workspace_id:wid,work_area_id:aid,task_name:name,priority,labels,description,due_time:dueTime,notify_enabled:notifyEnabled?1:0,is_billable:isBillable?1:0,billable_amount:isBillable?billableAmount:''});
