       if(!fresh)fresh=freshTasks.find(x=>String(x.id||'')===String(editId));
       if(!fresh){this.refreshStateQuietly();return;}
       const previousChecklist=Array.isArray(optimisticEditTask.checklist)?optimisticEditTask.checklist.slice():[];
       const previousSubtaskTotal=Math.max(Number(optimisticEditTask.subtask_total||0),previousChecklist.length);
       const previousSubtaskDone=Math.max(Number(optimisticEditTask.subtask_done||0),previousChecklist.filter(c=>Number(c.is_done)).length);
       Object.keys(optimisticEditTask).forEach(k=>delete optimisticEditTask[k]);
