       if(synced.length){const keepSubtasksOpen=synced.find('.bb-card-subtasks').hasClass('is-open');const bucket=String(synced.attr('data-current-bucket')||this.currentBucket(optimisticEditTask)||'');synced.replaceWith(this.taskCard(optimisticEditTask,bucket));if(keepSubtasksOpen){const refreshed=$(`.bb-task[data-task-id="${CSS.escape(String(optimisticEditTask.id||cid))}"]`).first();refreshed.find('.bb-card-subtasks').addClass('is-open');refreshed.find('[data-card-subtasks-toggle]').addClass('active').attr('aria-pressed','true').attr('title','Hide sub tasks').attr('aria-label','Hide sub tasks');}}
