simplifyTaskField(btn){
 const f=btn.closest('form');if(!f.length)return;
 const field=String(btn.attr('data-ai-simplify-task-field')||'task_name'),target=f.find(`[name="${field}"]`).first(),text=String(target.val()||'').trim();
 if(!target.length)return;
 const fieldWrap=target.closest('.bb-task-ai-field'),oldLabel=btn.attr('aria-label')||'Simplify with AI';
 fieldWrap.find('.bb-task-ai-preview,.bb-task-ai-inline-status').remove();
 if(!text){fieldWrap.append(`<div class="bb-task-ai-inline-status is-error">${field==='task_name'?'Enter or paste Task text first.':'Enter or paste instructions first.'}</div>`);target.focus();return;}
 const status=$('<div class="bb-task-ai-inline-status is-loading">✦ Simplifying with AI…</div>');fieldWrap.append(status);
 btn.prop('disabled',true).addClass('is-loading').attr('aria-label','Simplifying with AI…').text('…');
 this.api('bb_ai_simplify_task_text',{field,text}).done(r=>{
   if(!r?.success){status.removeClass('is-loading').addClass('is-error').text(r?.data?.message||'AI could not simplify the text.');return;}
   const simplified=String(r.data?.text||'').trim();if(!simplified){status.removeClass('is-loading').addClass('is-error').text('AI returned empty text. Please try again.');return;}
   status.remove();
   const preview=$(`<div class="bb-task-ai-preview"><div class="bb-task-ai-preview-head"><span>✦ AI Simplified</span><small>${this.esc(r.data?.provider||'AI')}</small></div><textarea class="bb-task-ai-result" rows="${field==='task_name'?2:4}" readonly></textarea><div class="bb-task-ai-preview-actions"><button type="button" class="bb-cancel-btn bb-btn light" data-ai-simplify-cancel>Cancel</button><button type="button" class="bb-btn primary" data-ai-simplify-replace data-ai-target-field="${this.attr(field)}">Replace</button></div></div>`);
   preview.find('.bb-task-ai-result').val(simplified);fieldWrap.append(preview);
 }).fail(xhr=>{const msg=xhr?.responseJSON?.data?.message||xhr?.responseJSON?.message||'AI request failed. Please try again.';status.removeClass('is-loading').addClass('is-error').text(msg);}).always(()=>{btn.prop('disabled',false).removeClass('is-loading').attr('aria-label',oldLabel).text('✦');});
},
applySimplifiedTaskText(btn){const preview=btn.closest('.bb-task-ai-preview'),form=btn.closest('form'),field=String(btn.attr('data-ai-target-field')||'task_name'),value=String(preview.find('.bb-task-ai-result').val()||'').trim(),target=form.find(`[name="${field}"]`).first();if(!target.length||!value)return;target.val(value).trigger('input').trigger('change');preview.remove();if(field==='task_name')this.refreshTaskNameValidation(form);target.focus();},
refreshTaskSummary(){const f=$('#bb-task-form');if(!f.length)return;const wid=f.find('[name=workspace_id]').val(),aid=f.find('[name=work_area_id]').val(),emp=f.find('[name=assignee_id] option:selected').text()||'Unassigned',priority=f.find('[name=priority]').val()||'Medium',type=f.find('[name=task_type]').val()||'One Time',freq=f.find('[name=frequency]').val()||'Daily';f.find('[data-summary="workspace"]').text(this.workspaceById(wid)?.name||'—');f.find('[data-summary="area"]').text(this.areaById(aid)?.name||'—');f.find('[data-summary="assignee"]').text(emp);f.find('[data-summary="priority"]').text(priority);f.find('[data-summary="type"]').text(type);let fr='—';if(type==='Recurring'){fr=freq==='Custom Interval'?`Every ${f.find('[name=interval_value]').val()||1} ${f.find('[name=interval_unit]').val()||'Days'}`:freq;}f.find('[data-summary="frequency"]').text(fr);},
refreshTaskAreaOptions(){const w=$('#bb-task-workspace');if(!w.length)return;const current=$('#bb-task-area').data('selected')||$('#bb-task-area').val()||'';const areas=this.areasForWorkspace(w.val());$('#bb-task-area').html(`<option value="">— Select Work Area —</option>`+areas.map(a=>`<option value="${a.id}" ${String(a.id)===String(current)?'selected':''}>${this.esc(a.name)}</option>`).join('')).data('selected','');},
