const safe=s=>this.esc(String(s??''));
const areaRows=areas.map(a=>{const ts=wsTasks.filter(t=>String(t.work_area_id)===String(a.id)&&String(t.status)!=='Cancelled'),done=ts.filter(t=>String(t.status)==='Completed').length,pct=ts.length?Math.round(done*100/ts.length):0;return `<label class="bb-settings-check"><input class="bb-settings-area-check" type="checkbox" value="${this.attr(a.id)}" ${selectedAreas.includes(String(a.id))?'checked':''}><span>${safe(a.name)} <small>[${done}/${ts.length} - ${pct}%]</small></span></label>`;}).join('');
const dueOptions=[['none','No Dates'],['overdue','Overdue'],['week','Task Due in This Week'],['today','Task Due Today'],['nextweek','Task Due in Next Week'],['month','Task Due in This Month'],['upcoming','All Upcoming Task']];
const dueRows=dueOptions.map(([value,name])=>`<label class="bb-settings-check"><input class="bb-settings-due-check" type="checkbox" value="${value}" ${selectedDue.includes(value)?'checked':''}><span>${name}</span></label>`).join('');
