loadTimeSheetTaskOptions(){if(this.timeSheetTaskCatalogLoading)return;this.timeSheetTaskCatalogLoading=true;this.api('bb_get_timesheet_task_options',{}).done(r=>{if(r.success){this.timeSheetTaskCatalog=r.data?.options||[];this.timeSheetTaskCatalogLoaded=true;if(this.view==='timesheet')this.renderTimeSheet();}else this.toast(r.data?.message||'Could not load Task options');}).fail(xhr=>this.toast(xhr.responseJSON?.data?.message||'Could not load Task options')).always(()=>{this.timeSheetTaskCatalogLoading=false;});},
