 const partyOptions=(currentParty&&!partyNames.includes(currentParty)?`<option value="${this.attr(currentParty)}" selected>${this.esc(currentParty)}</option>`:'')+activeParties.map(x=>{const name=String(x.party_name||x.name||'').trim();return name?`<option value="${this.attr(name)}" ${currentParty===name?'selected':''}>${this.esc(name)}</option>`:'';}).join('');
