saveCallSpaceEntry(form,createTask=false){const f=$(form);f.find('.bb-callspace-search-select').each((_,el)=>{const c=$(el),input=c.find('.bb-share-search-input').first(),select=c.find('select').first(),typed=String(input.val()||'').trim();if(!typed){select.val('');return;}if(String(select.val()||'')!=='')return;let matched='';select.find('option').each((__,o)=>{const v=String(o.value||''),label=String($(o).text()||'').trim();if(v&&(label.toLowerCase()===typed.toLowerCase()||v.toLowerCase()===typed.toLowerCase())){matched=v;return false;}});if(matched)select.val(matched);});const data={};f.serializeArray().forEach(x=>data[x.name]=x.value);const remarks=String(data.remarks||''),party=String(data.party||''),type=String(data.type||'Call');if(!party){this.toast('Select Party');return;}const btn=createTask?f.find('[data-callspace-create-task-submit]'):f.find('button[type=submit]'),release=this.startBusyButton(btn,createTask?'Saving…':'Saving…');this.api('bb_save_callspace_entry',data).done(r=>{if(!r.success){this.toast(r.data?.message||'Could not save CallSpace entry');return;}const entry=r.data?.entry;if(entry){const ix=(this.callSpaceRows||[]).findIndex(x=>String(x.id)===String(entry.id));if(ix>=0)this.callSpaceRows[ix]=entry;else this.callSpaceRows.unshift(entry);}this.callSpaceLoaded=true;this.closeModal();this.toast('CallSpace entry saved');if(createTask){setTimeout(()=>this.openTaskFromCallSpace(entry||data),80);}else if(this.view==='callspace')this.renderCallSpace();}).fail(xhr=>this.toast(xhr.responseJSON?.data?.message||'Could not save CallSpace entry')).always(()=>release());},
