saveSiteMessagingSettings(form){const data={};$(form).serializeArray().forEach(x=>data[x.name]=x.value);const $btn=$(form).find('button[type=submit],button:not([type])').last(),release=this.startBusyButton($btn,'Saving…');this.api('bb_save_site_messaging_settings',data).done(r=>{if(r.success){this.state.messagingSettings=r.data?.messagingSettings||this.state.messagingSettings;this.toast('Messaging settings saved');this.renderSettings();}else this.toast(r.data?.message||'Could not save messaging settings');}).fail(xhr=>this.toast(xhr.responseJSON?.data?.message||'Could not save messaging settings')).always(()=>release());},
