taskActionSheet(t){const baseId=t.template_id||t.id,occ=t.template_id?(t.occurrence_date||t.due_date||''):'',rec=!!t.template_id,scope=rec?'occurrence':'task';this.openModal(`<div class="bb-task-action-sheet bb-task-options-polished"><div class="bb-action-sheet-head"><div><span class="bb-eyebrow">TASK OPTIONS</span><h3>${this.formatMentionText(t.task_name)}</h3></div></div><div class="bb-action-list"><button type="button" class="bb-action-row archive" data-task-action-archive="${this.attr(baseId)}" data-occurrence-date="${this.attr(occ)}"><span class="bb-action-icon archive">▣</span><div><b>Archive Task</b></div><span class="bb-action-chevron">›</span></button><button type="button" class="bb-action-row activity" data-task-activity="${this.attr(t.id)}"><span class="bb-action-icon activity">◷</span><div><b>View Activity</b></div><span class="bb-action-chevron">›</span></button><button type="button" class="bb-action-row history" data-task-delete-history="${this.attr(baseId)}" data-occurrence-date="${this.attr(occ)}"><span class="bb-action-icon history">▤</span><div><b>Delete Activity</b></div><span class="bb-action-chevron">›</span></button><button type="button" class="bb-action-row delete" data-task-delete-mode="retain_activity" data-task-delete-scope="${scope}" data-task-id="${this.attr(baseId)}" data-occurrence-date="${this.attr(occ)}"><span class="bb-action-icon danger">🗑</span><div><b>Delete Task</b></div><span class="bb-action-chevron">›</span></button><button type="button" class="bb-action-row danger" data-task-delete-mode="all" data-task-delete-scope="${scope}" data-task-id="${this.attr(baseId)}" data-occurrence-date="${this.attr(occ)}"><span class="bb-action-icon danger">🗑</span><div><b>Delete Task &amp; Activity</b></div><span class="bb-action-chevron">›</span></button></div></div>`);},
