openTaskStagePicker(btn,t){if(!t)return;const stages=this.areaStages(t.work_area_id),current=this.taskStageName(t);const rows=stages.map(stage=>`<button type="button" class="bb-task-stage-option ${current.toLowerCase()===String(stage.name).toLowerCase()?'selected':''}" data-task-id="${this.attr(t.id)}" data-stage-name="${this.attr(stage.name)}" style="--stage-color:${this.attr(stage.color||'#64748b')}"><span class="bb-stage-choice-dot"></span><b>${this.esc(stage.name)}</b>${String(stage.name).toLowerCase()==='in progress'?'<small>Default stage</small>':''}</button>`).join('');const html=this.inlinePopoverShell('Task Stage',`<div class="bb-task-stage-menu">${rows}</div>`,'bb-stage-picker-pop');const pop=this.placeInlinePopover(btn,html);pop.on('click','.bb-task-stage-option',e=>{e.preventDefault();e.stopPropagation();const b=$(e.currentTarget);if(b.data('saving'))return;b.data('saving',1).addClass('is-saving');const id=String(b.attr('data-task-id')||''),stage=String(b.attr('data-stage-name')||'');this.setTaskStage(id,stage,pop,b);});},
setTaskStage(id,stageName,pop=null,button=null,remark='',skipRemarkPrompt=false){const stage=String(stageName||'').trim(),status=stage?'In Progress':'Pending',t=this.taskById(id);if(t&&this.workAreaRequiresUpdateRemark(t)&&!skipRemarkPrompt&&!String(remark||'').trim()){if(button)$(button).data('saving',0).removeClass('is-saving');if(pop)pop.remove();$(window).off('.bbInlinePopover');this.requestWorkflowRemark(t,stage?`Move to ${stage}`:'Clear Task Stage',r=>this.setTaskStage(id,stage,null,null,r,true));return;}this.api('bb_set_task_status',{task_id:id,status,stage_name:stage,remark:String(remark||'')}).done(r=>{if(r.success){if(t){t.status=status;t.stage_name=String(r.data?.stage_name??stage);if(remark)t.remark_count=Number(t.remark_count||0)+1;}if(pop)pop.remove();$(window).off('.bbInlinePopover');this.closeModal();this.toast(stage?`Moved to ${stage}`:'Stage cleared');this.render();this.refreshStateQuietly();}else{if(button)$(button).data('saving',0).removeClass('is-saving');this.toast(r.data?.message||'Could not update stage');}}).fail(xhr=>{if(button)$(button).data('saving',0).removeClass('is-saving');let msg='Could not update stage';try{if(xhr.responseJSON?.data?.message)msg=xhr.responseJSON.data.message;}catch(_e){}this.toast(msg);});},
openInProgressRemark(btn,t){
const active=t.status==='In Progress';
const html=this.inlinePopoverShell(active?'Add Progress Update':'Mark In Progress',`<form class="bb-inprogress-form" data-task-id="${this.attr(t.id)}"><textarea name="remark" rows="3" placeholder="Progress remark..." required></textarea><button type="submit" class="bb-btn primary bb-inprogress-submit">${active?'Add Update':'Mark In Progress'}</button></form>`,'bb-inprogress-pop');
const pop=this.placeInlinePopover(btn,html);pop.css('min-width','280px');requestAnimationFrame(()=>{pop.find('textarea').trigger('focus');if(!pop.is(':visible'))pop.css({display:'block',visibility:'visible',position:'fixed',left:'50%',top:'50%',transform:'translate(-50%,-50%)'});});
},
