exportAttendSpacePdf(){if(!this.isPrivilegedIdentity()){this.toast('PDF is available to Manager/Owner/Admin');return;}const dates=this.attendanceDateList(),userFilter=String(this.attendanceFilters.employee||''),statusFilter=String(this.attendanceFilters.status||''),rows=[];dates.forEach(date=>{const data=this.attendanceSelectedMonthData(date);this.attendanceEmployees().filter(emp=>Number(emp.attendance_enabled||0)===1).forEach(emp=>{if(userFilter&&String(emp.id)!==userFilter)return;if(emp.joined_on&&date<String(emp.joined_on))return;const ev=this.attendanceEventsFor(emp.id,date,data.events),st=this.attendanceDayMetrics(emp,date,ev,data.holidays,data.claims);if(statusFilter&&!this.attendanceMetricMatchesStatus(st,statusFilter))return;rows.push([this.formatDate(date),emp.name||'',st.firstIn?this.attendanceTime(st.firstIn):'—',st.lastOut?this.attendanceTime(st.lastOut):'—',this.attendanceBreakDisplay(st),st.netMinutes?this.attendanceMinutesLabel(st.netMinutes):'—',st.label||'',st.key==='short_hours'?this.attendanceHHMM(Math.max(0,Number(st.effectiveRequiredMinutes||0)-Number(st.netMinutes||0))):(st.key==='overtime'?this.attendanceHHMM(st.overtimeMinutes||0):'—')]);});});if(!rows.length){this.toast('No attendance rows to export');return;}const headers=['Date','Employee','IN','OUT','Break','Working Hour','Status','Time'];
// Generate a downloadable, paginated A4 landscape PDF without a print window.
const dateLabel=iso=>{const a=String(iso||'').slice(0,10).split('-');return a.length===3?`${a[2]}/${a[1]}/${a[0]}`:String(iso||'');};
const rangeLabel=dateLabel(dates[dates.length-1])+' to '+dateLabel(dates[0]);
const safeText=v=>(/^\s*[\u2014\u2013-]\s*$/.test(String(v??''))?'':String(v??'')).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[\u2012-\u2015]/g,'-').replace(/[\u2018\u2019]/g,"'").replace(/[\u201c\u201d]/g,'"').replace(/[^\x20-\x7e]/g,'-');
const escPdf=v=>safeText(v).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)');
const W=842,H=595,left=35,right=35,top=32,bottom=32,colWidths=[78,165,78,78,72,91,119,91],rowH=23,headH=26;
const objects=[null],add=obj=>{objects.push(obj);return objects.length-1;};
const font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');
const fontBold=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
const pagesRoot=add('');const pageIds=[];
const pdfColor=(r,g,b)=>`${r} ${g} ${b} rg`;
const textCmd=(value,x,y,size=9,bold=false)=>`0.10 0.15 0.24 rg BT /F${bold?2:1} ${size} Tf 1 0 0 1 ${x.toFixed(2)} ${(H-y).toFixed(2)} Tm (${escPdf(value)}) Tj ET\n`;
const rect=(x,y,w,h,color)=>`${pdfColor(...color)} ${x.toFixed(2)} ${(H-y-h).toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)} re f\n`;
const line=(x1,y1,x2,y2)=>`0.82 0.86 0.91 RG .5 w ${x1.toFixed(2)} ${(H-y1).toFixed(2)} m ${x2.toFixed(2)} ${(H-y2).toFixed(2)} l S\n`;
const charsFor=(value,width,fontSize)=>Math.max(2,Math.floor((width-11)/(fontSize*0.53)));
const shorten=(value,width,fontSize=8)=>{const str=safeText(value),count=charsFor(str,width,fontSize);return str.length>count?str.slice(0,Math.max(1,count-3))+'...':str;};
const rowsPerPage=Math.max(1,Math.floor((H-top-bottom-30-headH-14)/rowH));
const pagesCount=Math.ceil(rows.length/rowsPerPage);
for(let pageNumber=0;pageNumber<pagesCount;pageNumber++){
  let out='';
  out+=rect(left,top,W-left-right,headH,[0.93,0.95,0.98]);
  // Only centered date range; omit the Workboard/AttendSpace heading.
  out+=textCmd(rangeLabel,(W-rangeLabel.length*5.35)/2,top+17,10,true);
  const y0=top+headH+14;
  out+=rect(left,y0,W-left-right,rowH,[0.94,0.96,0.98]);
  let x=left;
  headers.forEach((head,i)=>{out+=textCmd(head,x+6,y0+15,9,true);x+=colWidths[i];});
  out+=line(left,y0,W-right,y0);out+=line(left,y0+rowH,W-right,y0+rowH);
  const part=rows.slice(pageNumber*rowsPerPage,(pageNumber+1)*rowsPerPage);
  part.forEach((r,ri)=>{const y=y0+rowH+ri*rowH;
    if(ri%2)out+=rect(left,y,W-left-right,rowH,[0.98,0.985,0.995]);
    x=left;r.forEach((v,i)=>{out+=textCmd(shorten(v,colWidths[i]),x+6,y+15,8,false);x+=colWidths[i];});
    out+=line(left,y+rowH,W-right,y+rowH);
  });
  x=left;out+=line(left,y0,x,y0+rowH*(part.length+1));
  colWidths.forEach(w=>{x+=w;out+=line(x,y0,x,y0+rowH*(part.length+1));});
  out+=textCmd(`Page ${pageNumber+1} of ${pagesCount}`,W-right-72,H-bottom+8,8,false);
  const length=new TextEncoder().encode(out).length;
  const streamId=add(`<< /Length ${length} >>\nstream\n${out}endstream`);
  const pageId=add(`<< /Type /Page /Parent ${pagesRoot} 0 R /MediaBox [0 0 ${W} ${H}] /Resources << /Font << /F1 ${font} 0 R /F2 ${fontBold} 0 R >> >> /Contents ${streamId} 0 R >>`);
  pageIds.push(pageId);
}
objects[pagesRoot]=`<< /Type /Pages /Kids [${pageIds.map(id=>id+' 0 R').join(' ')}] /Count ${pageIds.length} >>`;
const catalog=add(`<< /Type /Catalog /Pages ${pagesRoot} 0 R >>`);
let pdf='%PDF-1.4\n',offsets=[0];
for(let id=1;id<objects.length;id++){offsets[id]=new TextEncoder().encode(pdf).length;pdf+=`${id} 0 obj\n${objects[id]}\nendobj\n`;}
const xrefStart=new TextEncoder().encode(pdf).length;
pdf+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;
for(let id=1;id<objects.length;id++)pdf+=`${String(offsets[id]).padStart(10,'0')} 00000 n \n`;
pdf+=`trailer\n<< /Size ${objects.length} /Root ${catalog} 0 R >>\nstartxref\n${xrefStart}\n%%EOF`;
const blob=new Blob([pdf],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');
a.href=url;a.download=`AttendSpace_${dateLabel(dates[dates.length-1]).replace(/\//g,'-')}_to_${dateLabel(dates[0]).replace(/\//g,'-')}.pdf`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);
},
exportAttendSpaceExcel(){if(!this.isPrivilegedIdentity()){this.toast('Excel export is available to Manager/Owner/Admin');return;}const allEmps=this.attendanceEmployees(),userFilter=String(this.attendanceFilters.employee||''),statusFilter=String(this.attendanceFilters.status||''),dates=this.attendanceDateList(),rows=[];dates.forEach(date=>{const monthData=this.attendanceSelectedMonthData(date);allEmps.forEach(emp=>{if(userFilter&&String(emp.id)!==userFilter)return;const eligibleFrom=String(emp.joined_on||'');if(eligibleFrom&&date<eligibleFrom)return;const events=this.attendanceEventsFor(emp.id,date,monthData.events),st=this.attendanceDayMetrics(emp,date,events,monthData.holidays,monthData.claims);if(statusFilter&&!this.attendanceMetricMatchesStatus(st,statusFilter))return;const timeValue=st.key==='short_hours'?this.attendanceHHMM(Math.max(0,Number(st.effectiveRequiredMinutes||0)-Number(st.netMinutes||0))):(st.key==='overtime'?this.attendanceHHMM(st.overtimeMinutes||0):'');rows.push([this.formatDate(date),emp.name||'',st.firstIn?this.attendanceTime(st.firstIn):'',st.lastOut?this.attendanceTime(st.lastOut):'',this.attendanceBreakDisplay(st)==='—'?'':this.attendanceBreakDisplay(st),st.netMinutes?this.attendanceMinutesLabel(st.netMinutes):'',st.label||'',timeValue]);});});if(!rows.length){this.toast('No attendance rows to export');return;}const from=this.attendanceFilters.from||'',to=this.attendanceFilters.to||'',range=from&&to?(from===to?from:`${from}-to-${to}`):(this.state.attendanceToday||'attendance');this.downloadExcel(`Workboard-AttendSpace-${range}.xls`,['Date','Employee','In','Out','Break','Working Hour','Status','Time'],rows);},
captureAttendanceFilters(){this.attendanceFilters={from:String($('#bb-att-filter-from').val()||''),to:String($('#bb-att-filter-to').val()||''),employee:String($('#bb-att-filter-user').val()||''),status:String($('#bb-att-filter-status').val()||'')};this.renderAttendSpace();},
