// v4.13.14 — capture-phase searchable dropdown fallback.
// Some legacy Workboard handlers stop bubbling inside Quick Add panels, so document-level jQuery
// delegated input handlers may never receive the event. Capture phase runs before those handlers.
document.addEventListener('input',function(e){
  const input=e.target;
  if(!input||!input.matches)return;
  let list,rows,noResults,q=String(input.value||'').trim().toLowerCase();
  if(input.matches('.bb-quick-people-search')){
    list=input.closest('.bb-quick-people-list');
    if(!list)return;
    rows=Array.from(list.children).filter(el=>el.classList&&el.classList.contains('bb-quick-person'));
    noResults=list.querySelector('.bb-quick-people-no-results');
  }else if(input.matches('.bb-filter-search-input')){
    list=input.closest('.bb-multi-menu');
    if(!list)return;
    rows=Array.from(list.children).filter(el=>el.tagName==='LABEL');
    noResults=list.querySelector('.bb-filter-no-results');
  }else{return;}
  let shown=0;
  rows.forEach(row=>{
    const match=String(row.textContent||'').toLowerCase().includes(q);
    row.hidden=!match;
    row.classList.toggle('bb-search-option-hidden',!match);
    row.setAttribute('aria-hidden',match?'false':'true');
    row.style.setProperty('display',match?'flex':'none','important');
    if(match)shown++;
  });
  if(noResults){
    const show=!!q&&shown===0;
    noResults.hidden=!show;
    noResults.style.setProperty('display',show?'block':'none','important');
  }
},true);

// v4.16.132 — normalize delete/remove controls to the approved solid red trash icon, including modals.
(function(){
  const trashSvg='<svg class="bb-delete-trash-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M8.2 2.5h7.6l.8 2.2H20a1 1 0 0 1 1 1v1.8H3V5.7a1 1 0 0 1 1-1h3.4l.8-2.2ZM5.2 9h13.6l-.8 10.3a2 2 0 0 1-2 1.8H8a2 2 0 0 1-2-1.8L5.2 9Z"/><path d="M9.5 12v5.5M14.5 12v5.5" fill="none" stroke="#fff" stroke-width="1.8" stroke-linecap="round"/></svg>';
  const excluded=['bb-modal-close','bb-modal-x','bb-drawer-close','bb-inline-pop-close','bb-card-subtask-add-cancel','bb-keep-new-cancel','bb-workarea-add-unified'];
  const isDeleteControl=(btn)=>{
    if(!btn||btn.tagName!=='BUTTON')return false;
    if(excluded.some(c=>btn.classList.contains(c)))return false;
    // v4.16.189: preserve the polished Task Options / confirmation UI.
    // These controls intentionally contain text + icons and must not be converted
    // into the global icon-only trash button.
    if(btn.closest('.bb-task-options-polished'))return false;
    if(btn.closest('.bb-delete-confirm-actions'))return false;
    // Task-card action icons are functional actions, not delete controls.
    // Keep their original SVGs (Activity, Focus, Reminder, Urgent, Move, Flash, Copy, Edit).
    if(btn.closest('.bb-task-bottom-actions'))return false;
    if(btn.matches('.bb-task-bottom-activity,.bb-task-bottom-focus,.bb-task-bottom-reminder,.bb-task-bottom-urgent,.bb-task-bottom-move,.bb-task-bottom-flash,.bb-task-bottom-copy,.bb-task-bottom-edit'))return false;
    // Focus uses the word "Remove" when active, but it is not a delete action.
    if(btn.hasAttribute('data-task-focus'))return false;
    const attrs=Array.from(btn.attributes||[]).map(a=>String(a.name||'').toLowerCase());
    if(attrs.some(n=>n.startsWith('data-delete')||n.startsWith('data-remove')||n.includes('-delete-')||n.includes('-remove-')))return true;
    const cls=String(btn.className||'').toLowerCase();
    if(/(^|\s|[-_])(delete|remove|trash)([-_]|\s|$)/.test(cls))return true;
    const title=(String(btn.getAttribute('title')||'')+' '+String(btn.getAttribute('aria-label')||'')).toLowerCase();
    if(/\b(delete|remove|trash)\b/.test(title))return true;
    const text=String(btn.textContent||'').trim().toLowerCase();
    return /^(delete|remove)(\s+(row|entry|item|task|sub ?task|reminder|attachment|file|attendance|workspace|work area|notespace|record))?$/.test(text);
  };
  const normalize=(root=document)=>{
    const buttons=[];
    if(root.nodeType===1&&root.matches&&root.matches('button'))buttons.push(root);
    if(root.querySelectorAll)buttons.push(...root.querySelectorAll('button'));
    buttons.forEach(btn=>{
      if(!isDeleteControl(btn))return;
      const oldText=String(btn.getAttribute('aria-label')||btn.getAttribute('title')||btn.textContent||'Delete').trim();
      if(!btn.getAttribute('title'))btn.setAttribute('title',oldText||'Delete');
      if(!btn.getAttribute('aria-label'))btn.setAttribute('aria-label',oldText||'Delete');
      btn.classList.add('bb-unified-delete-button');
      if(!btn.querySelector('.bb-delete-trash-icon'))btn.innerHTML=trashSvg;
    });
  };
  const start=()=>{
    normalize(document);
    const target=document.body;
    if(!target)return;
    const observer=new MutationObserver(records=>records.forEach(r=>r.addedNodes.forEach(n=>{if(n.nodeType===1)normalize(n);}))); 
    observer.observe(target,{childList:true,subtree:true});
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();

