// v4.16.178 / v4.17.8 — only the clicked sub-task row shows its delete icon.
// WordPress runs jQuery in noConflict mode, so keep this helper inside a jQuery scope.
(function($){
$(document).on('click.bbSubtaskDeleteReveal','.bb-inline-subtask-row,.bb-card-subtask-row,.bb-detail-subtask-row',function(e){
  if($(e.target).closest('.bb-subtask-delete-action').length)return;
  const row=$(this);
  $('.bb-subtask-delete-visible').not(row).removeClass('bb-subtask-delete-visible');
  row.addClass('bb-subtask-delete-visible');
});
$(document).on('click.bbSubtaskDeleteRevealOutside',function(e){
  if($(e.target).closest('.bb-inline-subtask-row,.bb-card-subtask-row,.bb-detail-subtask-row').length)return;
  $('.bb-subtask-delete-visible').removeClass('bb-subtask-delete-visible');
});
})(jQuery);


// v4.18.81 - Login password visibility toggle (WordPress jQuery noConflict safe)
(function($){
  $(document).off('click.bbPasswordToggle','.bb-password-toggle').on('click.bbPasswordToggle','.bb-password-toggle',function(e){
    e.preventDefault();
    const btn=$(this);
    const input=btn.closest('.bb-password-wrap').find('input[name="password"]');
    if(!input.length) return;
    const show=input.prop('type')==='password';
    input.prop('type',show?'text':'password');
    btn.toggleClass('is-visible',show)
      .attr('aria-pressed',show?'true':'false')
      .attr('aria-label',show?'Hide password':'Show password')
      .attr('title',show?'Hide password':'Show password');
    input.trigger('focus');
  });
})(jQuery);


